// src/shaders/minimalist/mid-a.wgsl.js
var midaWGSL2 = () => `
override shadowDepthTextureSize: f32 = ${MEConfig.SHADOW_RES};

struct Scene {
    lightViewProjMatrix  : mat4x4f,
    cameraViewProjMatrix : mat4x4f,
    cameraPos            : vec3f,
    padding2             : f32,
    lightPos             : vec3f,
    padding              : f32,
    globalAmbient        : vec3f,
    padding3             : f32,
    time                 : f32,
    deltaTime            : f32,
    padding4             : vec2f,
};

struct MaterialPBR {
    baseColorFactor : vec4f,
    metallicFactor  : f32,
    roughnessFactor : f32,
    effectMix       : f32,
    lightingEnabled : f32,
    ambientColor    : vec3f,  // add this
    _pad            : f32,    // alignment padding
};

struct SpotLight {
    position      : vec3f,
    _pad1         : f32,
    direction     : vec3f,
    _pad2         : f32,
    innerCutoff   : f32,
    outerCutoff   : f32,
    intensity     : f32,
    _pad3         : f32,
    color         : vec3f,
    _pad4         : f32,
    range         : f32,
    ambientFactor : f32,
    shadowBias    : f32,
    _pad5         : f32,
    lightViewProj : mat4x4<f32>,
};

const MAX_SPOTLIGHTS = ${MEConfig.MAX_SPOTLIGHTS}u;

@group(0) @binding(0) var<uniform> scene : Scene;
@group(0) @binding(1) var shadowMapArray: texture_depth_2d_array;
@group(0) @binding(2) var shadowSampler: sampler_comparison;
@group(1) @binding(0) var meshTexture: texture_2d<f32>;
@group(1) @binding(1) var meshSampler: sampler;
@group(0) @binding(3) var<storage, read> spotlights: array<SpotLight, MAX_SPOTLIGHTS>;
@group(1) @binding(2) var metallicRoughnessTex: texture_2d<f32>;
@group(1) @binding(3) var metallicRoughnessSampler: sampler;
@group(1) @binding(4) var<uniform> material: MaterialPBR;

struct FragmentInput {
    @location(0) shadowPos : vec4f,
    @location(1) fragPos   : vec3f,
    @location(2) fragNorm  : vec3f,
    @location(3) uv        : vec2f,
};

struct FragOut {
  @location(0) color  : vec4f,
  @location(1) normal : vec4f,
  @location(2) worldPos : vec4f,
}

@fragment
fn main(input: FragmentInput) -> FragOut {

    let texColor = textureSample(meshTexture, meshSampler, input.uv);
    let baseColor = texColor.rgb * material.baseColorFactor.rgb;

    let N = normalize(input.fragNorm);
    let V = normalize(scene.cameraPos - input.fragPos);

    // ===== FAKE LIGHT (single directional from lightPos) =====
    let L = normalize(scene.lightPos - input.fragPos);

    // ===== HALF-LAMBERT (softer shading) =====
    let NdotL = dot(N, L);
    let diffuse = NdotL * 0.5 + 0.5; // smoother than max(dot,0)

    // ===== CHEAP SPECULAR (Blinn-Phong lite) =====
    let H = normalize(L + V);
    let specPower = mix(8.0, 64.0, 1.0 - material.roughnessFactor);
    let spec = pow(max(dot(N, H), 0.0), specPower);

    // ===== CHEAP FRESNEL =====
    let fresnel = pow(1.0 - max(dot(N, V), 0.0), 3.0);

    // ===== COMBINE =====
    var lighting = scene.globalAmbient;

    lighting += diffuse * 0.8;      // diffuse light
    lighting += spec * 0.3;         // highlight
    lighting += fresnel * 0.2;      // edge glow

    let finalColor = baseColor * lighting;

    let alpha = texColor.a * material.baseColorFactor.a;
    if(alpha < 0.01) {
        discard;
    }

    // return vec4f(finalColor, alpha);
    return FragOut(
      vec4f(finalColor, alpha),
      vec4f(N, 0.0),
      vec4f(input.fragPos, 1.0)
    );
}
`;

// src/shaders/minimalist/hybrid.wgsl.js
var hybridWGSL = () => `
override shadowDepthTextureSize: f32 = ${MEConfig.SHADOW_RES};

struct Scene {
    lightViewProjMatrix  : mat4x4f,
    cameraViewProjMatrix : mat4x4f,
    cameraPos            : vec3f,
    padding2             : f32,
    lightPos             : vec3f,
    padding              : f32,
    globalAmbient        : vec3f,
    padding3             : f32,
    time                 : f32,
    deltaTime            : f32,
    padding4             : vec2f,
};

struct MaterialPBR {
    baseColorFactor : vec4f,
    metallicFactor  : f32,
    roughnessFactor : f32,
    effectMix       : f32,
    lightingEnabled : f32,
    ambientColor    : vec3f,  // add this
    _pad            : f32,    // alignment padding
};

struct SpotLight {
    position      : vec3f,
    _pad1         : f32,
    direction     : vec3f,
    _pad2         : f32,
    innerCutoff   : f32,
    outerCutoff   : f32,
    intensity     : f32,
    _pad3         : f32,
    color         : vec3f,
    _pad4         : f32,
    range         : f32,
    ambientFactor : f32,
    shadowBias    : f32,
    _pad5         : f32,
    lightViewProj : mat4x4<f32>,
};

const MAX_SPOTLIGHTS = ${MEConfig.MAX_SPOTLIGHTS}u;

@group(0) @binding(0) var<uniform> scene : Scene;
@group(1) @binding(0) var meshTexture: texture_2d<f32>;
@group(1) @binding(1) var meshSampler: sampler;
@group(1) @binding(4) var<uniform> material: MaterialPBR;

struct FragmentInput {
    @location(1) fragPos   : vec3f,
    @location(2) fragNorm  : vec3f,
    @location(3) uv        : vec2f,
};

struct FragOut {
  @location(0) color  : vec4f,
  @location(1) normal : vec4f,
  @location(2) worldPos : vec4f,
}

@fragment
fn main(input: FragmentInput) -> FragOut {
  let texColor = textureSample(meshTexture, meshSampler, input.uv);
  let baseColor = texColor.rgb * material.baseColorFactor.rgb;
  let N = normalize(input.fragNorm);
  let V = normalize(scene.cameraPos - input.fragPos);
  let L = normalize(scene.lightPos - input.fragPos);
  // ===== DISTANCE BASED LOD =====
  let dist = distance(scene.cameraPos, input.fragPos);
  // tweak these!
  let nearDist = 50.0;
  let farDist  = 200.0;
  let lodFactor = clamp((dist - nearDist) / (farDist - nearDist), 0.0, 1.0);
  // ===== CHEAP =====
  let cheapLighting = scene.globalAmbient;
  // ===== MID QUALITY =====
  let NdotL = dot(N, L);
  let diffuse = NdotL * 0.5 + 0.5;
  let H = normalize(L + V);
  let specPower = mix(8.0, 64.0, 1.0 - material.roughnessFactor);
  let spec = pow(max(dot(N, H), 0.0), specPower);
  let fresnel = pow(1.0 - max(dot(N, V), 0.0), 3.0);
  var midLighting = scene.globalAmbient;
  midLighting += diffuse * 0.8;
  midLighting += spec * 0.3;
  midLighting += fresnel * 0.2;
  // ===== FINAL BLEND =====
  let lighting = mix(midLighting, cheapLighting, lodFactor);
  let finalColor = baseColor * lighting;
  // ===== DISTANCE FOG (BONUS \u{1F525}) =====
  let fogStart = 150.0;
  let fogEnd   = 400.0;
  let fogFactor = clamp((dist - fogStart) / (fogEnd - fogStart), 0.0, 1.0);
  let fogColor = vec3f(0.6, 0.7, 0.8);
  let colorWithFog = mix(finalColor, fogColor, fogFactor);
  let alpha = texColor.a * material.baseColorFactor.a;
  if(alpha < 0.01) {
      discard;
  }
  // return vec4f(colorWithFog, alpha);
  let alpha = 1.0;
  return FragOut(
    vec4f(colorWithFog, alpha),
    vec4f(N, 0.0),
    vec4f(input.fragPos, 1.0)
  );
}
`;

