function serializeGraph(shaderGraph) {
  return JSON.stringify({
    nodes: shaderGraph.nodes.map((n3) => ({
      id: n3.id,
      type: n3.type,
      x: n3.x ?? 100,
      y: n3.y ?? 100,
      fnName: n3.fnName,
      code: n3.code,
      name: n3.name,
      value: n3.value,
      r: n3.r,
      g: n3.g,
      b: n3.b,
      a: n3.a,
      inputs: Object.fromEntries(Object.entries(n3.inputs || {}).map(([k2, v2]) => [k2, { default: v2.default }])),
      valueX: n3.valueX,
      valueY: n3.valueY,
      valueZ: n3.valueZ,
      valueW: n3.valueW
    })),
    connections: shaderGraph.connections.map((c2) => ({
      from: c2.fromNode.id,
      fromPin: c2.fromPin,
      to: c2.toNode.id,
      toPin: c2.toPin
    })),
    final: shaderGraph.runtime_memory[shaderGraph.id] ? shaderGraph.runtime_memory[shaderGraph.id] : null
  });
}
function saveGraph(shaderGraph, key = "fragShaderGraph") {
  let content = serializeGraph(shaderGraph);
  localStorage.setItem(key, content);
  if (shaderGraph.runtime_memory[key]) {
  } else {
    console.warn("GraphShader is saved for src but with no compile final data for prod build.");
  }
  document.dispatchEvent(new CustomEvent("save-shader-graph", {
    detail: {
      name: key,
      content
    }
  }));
  console.log("%cShader shaderGraph saved", LOG_FUNNY_ARCADE);
}
async function loadGraph(key, shaderGraph, addNodeUI) {
  if (shaderGraph.onGraphLoadAttached === false) {
    shaderGraph.onGraphLoadAttached = true;
    document.addEventListener("on-graph-load", (e2) => {
      if (e2.detail == null) {
        return;
      }
      shaderGraph.nodes.length = 0;
      shaderGraph.connections.length = 0;
      shaderGraph.id = e2.detail.name;
      let data;
      if (typeof e2.detail.content === "object") {
        data = e2.detail.content;
      } else {
        data = JSON.parse(e2.detail.content);
      }
      if (!data) return false;
      const map = {};
      data.nodes.forEach((node2) => {
        const saveId = node2.id;
        const saveX = node2.x;
        const saveY = node2.y;
        switch (node2.type) {
          case "FragmentOutput":
            node2 = new FragmentOutputNode();
            break;
          case "CameraPos":
            node2 = new CameraPosNode();
            break;
          case "MultiplyVec2":
            node2 = new MultiplyVec2Node();
            break;
          case "AddVec2":
            node2 = new AddVec2Node();
            break;
          case "Time":
            node2 = new TimeNode();
            break;
          case "InlineFunction":
            node2 = new InlineFunctionNode(node2.fnName, node2.code);
            break;
          case "TextureSampler":
            node2 = new TextureSamplerNode(node2.name);
            break;
          case "MultiplyColor":
            node2 = new MultiplyColorNode();
            break;
          case "Grayscale":
            node2 = new GrayscaleNode();
            break;
          case "Contrast":
            node2 = new ContrastNode();
            break;
          case "AlphaOutput":
            node2 = new AlphaOutput();
            break;
          case "NormalOutput":
            node2 = new NormalOutput();
            break;
          case "LightShadowNode":
            node2 = new LightShadowNode();
            break;
          case "LightToColor":
            node2 = new LightToColorNode();
            break;
          case "UV":
            node2 = new UVNode();
            break;
          case "Float":
            node2 = new FloatNode(node2.value ?? 1);
            break;
          case "Vec2":
            node2 = new Vec2Node(node2.valueX ?? 0, node2.valueY ?? 0);
            break;
          case "Vec3":
            node2 = new Vec3Node(node2.valueX ?? 0, node2.valueY ?? 0, node2.valueZ ?? 0);
            break;
          case "Vec4":
            node2 = new Vec4Node(node2.valueX ?? 0, node2.valueY ?? 0, node2.valueZ ?? 0, node2.valueW ?? 1);
            break;
          case "Color":
            node2 = new ColorNode(node2.r ?? 1, node2.g ?? 1, node2.b ?? 1, node2.a ?? 1);
            break;
          case "Add":
            node2 = new AddNode();
            break;
          case "Subtract":
            node2 = new SubtractNode();
            break;
          case "Multiply":
            node2 = new MultiplyNode();
            break;
          case "Divide":
            node2 = new DivideNode();
            break;
          case "Power":
            node2 = new PowerNode();
            break;
          case "Sin":
            node2 = new SinNode();
            break;
          case "Cos":
            node2 = new CosNode();
            break;
          case "Normalize":
            node2 = new NormalizeNode();
            break;
          case "DotProduct":
            node2 = new DotProductNode();
            break;
          case "Lerp":
            node2 = new LerpNode();
            break;
          case "Frac":
            node2 = new FracNode();
            break;
          case "OneMinus":
            node2 = new OneMinusNode();
            break;
          case "Smoothstep":
            node2 = new SmoothstepNode();
            break;
          case "FragmentPosition":
            node2 = new FragmentPositionNode();
            break;
          case "ViewDirection":
            node2 = new ViewDirectionNode();
            break;
          case "SplitVec4":
            node2 = new SplitVec4Node();
            break;
          case "CombineVec4":
            node2 = new CombineVec4Node();
            break;
          case "GlobalAmbient":
            node2 = new GlobalAmbientNode();
            break;
        }
        node2.id = saveId;
        node2.x = saveX;
        node2.y = saveY;
        map[node2.id] = node2;
        addNodeUI(node2, node2.x, node2.y);
      });
      setTimeout(() => data.connections.forEach((c2) => {
        const fromNode = map[c2.from];
        const toNode = map[c2.to];
        const fromPin = c2.fromPin;
        const toPin = c2.toPin;
        if (!fromNode || !toNode) {
          console.warn("Skipping connection due to missing node", c2);
          return;
        }
        shaderGraph.connect(fromNode, fromPin, toNode, toPin);
        const path2 = shaderGraph.connectionLayer.path();
        path2.dataset.from = `${fromNode.id}:${fromPin}`;
        path2.dataset.to = `${toNode.id}:${toPin}`;
        shaderGraph.connectionLayer.svg.appendChild(path2);
        shaderGraph.connectionLayer.redrawAll(path2);
      }), 50);
      return true;
    });
  }
  document.dispatchEvent(new CustomEvent("load-shader-graph", { detail: key }));
}

// src/tools/editor/curve-editor.js
var CurveEditor = class {
  constructor({ width = 651, height = 300, samples = 128 } = {}) {
    this.curveStore = new CurveStore();
    this.width = width;
    this.height = height;
    this.samples = samples;
    this.keys = [
      { time: 0, value: 0, inTangent: 0, outTangent: 0 },
      { time: 1, value: 0, inTangent: 0, outTangent: 0 }
    ];
    this.valueMin = -1;
    this.valueMax = 1;
    this.padLeft = 32;
    this.padBottom = 18;
    this.canvas = document.createElement("canvas");
    this.canvas.width = width;
    this.canvas.height = height;
    this.ctx = this.canvas.getContext("2d");
    this.zeroY = Math.round(this.height * 0.5) + 0.5;
    this.graphHeight = this.height - this.padBottom;
    this.snapEnabled = true;
    this.snapSteps = 20;
    this.snapValueSteps = 20;
    this.name = "Curve";
    this.currentValue = 0;
    this.value = 0;
    this.activeKey = null;
    this.dragMode = null;
    this._grabDX = 0;
    this._grabDY = 0;
    this.time = 0;
    this.loop = true;
    this.speed = 1;
    this.isGraphRunning = false;
    this._editorOpen = false;
    this._createPopup();
    this._bindMouse();
    this._buildToolbar();
    this._enableDrag();
    this.length = 1;
    this._lastTime = performance.now();
    this._runner = null;
    this.baked = this.bake(samples);
    setTimeout(() => this.draw(), 100);
  }
  _valueToY(v2) {
    const n3 = (v2 - this.valueMin) / (this.valueMax - this.valueMin);
    return (1 - n3) * this.graphHeight;
  }
  _yToValue(y3) {
    const n3 = 1 - y3 / this.height;
    return this.valueMin + n3 * (this.valueMax - this.valueMin);
  }
  _snap(value, steps) {
    if (!this.snapEnabled) return value;
    const range = this.valueMax - this.valueMin;
    return Math.round((value - this.valueMin) / range * steps) / steps * range + this.valueMin;
  }
  // VALUE EVALUATION (HERMITE)
  getValue(t3) {
    t3 = Math.max(0, Math.min(1, t3));
    for (let i2 = 0; i2 < this.keys.length - 1; i2++) {
      const k0 = this.keys[i2];
      const k1 = this.keys[i2 + 1];
      if (t3 >= k0.time && t3 <= k1.time) {
        const dt2 = k1.time - k0.time;
        const u2 = (t3 - k0.time) / dt2;
        const u22 = u2 * u2;
        const u3 = u22 * u2;
        const m0 = k0.outTangent * dt2;
        const m1 = k1.inTangent * dt2;
        return (2 * u3 - 3 * u22 + 1) * k0.value + (u3 - 2 * u22 + u2) * m0 + (-2 * u3 + 3 * u22) * k1.value + (u3 - u22) * m1;
      }
    }
    return this.keys.at(-1).value;
  }
  // DRAW
  draw() {
    const padLeft = 32;
    const padBottom = 18;
    const ctx = this.ctx;
    const w2 = this.width - padLeft;
    const h2 = this.height - padBottom;
    ctx.save();
    ctx.translate(padLeft, 0);
    ctx.clearRect(-50, -50, w2 + padLeft + 50, h2 + padBottom + 50);
    ctx.fillStyle = "#0b0f14";
    ctx.fillRect(0, 0, w2, h2);
    ctx.strokeStyle = "#1c2533";
    for (let i2 = 0; i2 <= 10; i2++) {
      const x3 = i2 / 10 * w2;
      const y4 = i2 / 10 * h2;
      ctx.beginPath();
      ctx.moveTo(x3, 0);
      ctx.lineTo(x3, h2);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, y4);
      ctx.lineTo(w2, y4);
      ctx.stroke();
    }
    ctx.fillStyle = "#9aa7b2";
    ctx.font = "11px monospace";
    ctx.textAlign = "right";
    ctx.textBaseline = "middle";
    ctx.fillText("+1", -6, this._valueToY(0.9));
    ctx.fillText("0", -6, this._valueToY(0));
    ctx.fillText("-1", -6, this._valueToY(-0.9));
    const zeroY = this._valueToY(0);
    ctx.strokeStyle = "#2e3b4e";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, zeroY);
    ctx.lineTo(w2, zeroY);
    ctx.stroke();
    ctx.lineWidth = 1;
    ctx.strokeStyle = "#4fc3f7";
    ctx.beginPath();
    for (let i2 = 0; i2 <= 100; i2++) {
      const t3 = i2 / 100;
      const x3 = t3 * w2;
      const y4 = this._valueToY(this.getValue(t3));
      i2 === 0 ? ctx.moveTo(x3, y4) : ctx.lineTo(x3, y4);
    }
    ctx.stroke();
    this.keys.forEach((k2) => {
      const x3 = this._timeToX(k2.time);
      const y4 = this._valueToY(k2.value);
      ctx.strokeStyle = "#888";
      ctx.beginPath();
      ctx.moveTo(x3, y4);
      ctx.lineTo(x3 + 30, y4 - k2.outTangent * 30);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(x3, y4);
      ctx.lineTo(x3 - 30, y4 + k2.inTangent * 30);
      ctx.stroke();
      ctx.fillStyle = "#ffcc00";
      ctx.beginPath();
      ctx.arc(x3, y4, 4, 0, Math.PI * 2);
      ctx.fill();
    });
    const playX = this._timeToX(this.time);
    const playY = this._valueToY(this.getValueNow());
    ctx.strokeStyle = "#ff5555";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(playX, 0);
    ctx.lineTo(playX, h2);
    ctx.stroke();
    ctx.fillStyle = "#ff5555";
    ctx.beginPath();
    ctx.arc(playX, playY, 5, 0, Math.PI * 2);
    ctx.fill();
    ctx.lineWidth = 1;
    ctx.restore();
    ctx.fillStyle = "#ffffffff";
    ctx.font = "13px monospace";
    ctx.textAlign = "center";
    ctx.textBaseline = "top";
    const y3 = this.height - padBottom + 2;
    ctx.fillText("0s", padLeft, y3);
    ctx.fillText(
      (this.length * 0.5).toFixed(2) + "s",
      padLeft + w2 * 0.5,
      y3
    );
    ctx.fillText(
      this.length.toFixed(2) + "s",
      padLeft + w2,
      y3
    );
    this._updateToolbar();
  }
  _getMouse(e2) {
    const r3 = this.canvas.getBoundingClientRect();
    return {
      x: e2.clientX - r3.left - this.padLeft,
      y: e2.clientY - r3.top
    };
  }
  _bindMouse() {
    const hitKey = (mx, my) => {
      return this.keys.find((k2) => {
        const x3 = this._timeToX(k2.time);
        const y3 = this._valueToY(k2.value);
        const HIT_RADIUS = 20;
        return Math.hypot(mx - x3, my - y3) <= HIT_RADIUS;
      });
    };
    const hitPlayhead = (mx, my) => {
      if (this.isGraphRunning) return false;
      const w2 = this.width - this.padLeft;
      const playX = this._timeToX(this.time);
      const playY = this._valueToY(this.getValueNow());
      return Math.hypot(mx - playX, my - playY) < 8;
    };
    this.canvas.addEventListener("mousedown", (e2) => {
      const { x: mx, y: my } = this._getMouse(e2);
      if (hitPlayhead(mx, my)) {
        this.activeKey = "playhead";
        this.dragMode = "playhead";
        return;
      }
      const k2 = hitKey(mx, my);
      if (k2) {
        const w2 = this.width - this.padLeft;
        const kx = k2.time * w2;
        const ky = this._valueToY(k2.value);
        this._grabDX = mx - kx;
        this._grabDY = my - ky;
        this.activeKey = k2;
        this.dragMode = e2.shiftKey ? "tangent" : "key";
      }
    });
    window.addEventListener("mousemove", (e2) => {
      if (!this.activeKey) return;
      const { x: mx, y: my } = this._getMouse(e2);
      if (this.dragMode === "playhead" && this.activeKey === "playhead") {
        const w2 = this.width - this.padLeft;
        let t3 = Math.max(0, Math.min(1, mx / w2));
        t3 = this._snap(t3, this.snapSteps);
        this.time = t3;
        this.draw();
        return;
      }
      if (this.dragMode === "key") {
        const w2 = this.width - this.padLeft;
        let t3 = (mx - this._grabDX) / w2;
        t3 = Math.max(0, Math.min(1 - 1e-6, t3));
        let v2 = this._yToValue(my - this._grabDY);
        v2 = Math.max(this.valueMin, Math.min(this.valueMax, v2));
        v2 = this._snap(v2, this.snapValueSteps);
        t3 = this._snap(t3, this.snapSteps);
        v2 = this._snap(v2, this.snapValueSteps);
        this.activeKey.time = t3;
        this.activeKey.value = v2;
        this.keys.sort((a2, b2) => a2.time - b2.time);
      }
      if (this.dragMode === "tangent") {
        const dx = mx / r.width - this.activeKey.time;
        const dy = 1 - my / r.height - this.activeKey.value;
        this.activeKey.outTangent = dy / dx || 0;
        this.activeKey.inTangent = this.activeKey.outTangent;
      }
      this.draw();
      this._reBake();
    });
    window.addEventListener("mouseup", () => {
      this.activeKey = null;
      this.dragMode = null;
    });
    this.canvas.addEventListener("dblclick", (e2) => {
      const { x: x3, y: y3 } = this._getMouse(e2);
      const w2 = this.width - this.padLeft;
      const t3 = Math.max(0, Math.min(1, x3 / w2));
      const v2 = this._yToValue(y3);
      this.keys.push({
        time: t3,
        value: v2,
        inTangent: 0,
        outTangent: 0
      });
      this.keys.sort((a2, b2) => a2.time - b2.time);
      this._reBake();
      this.draw();
    });
    this.canvas.addEventListener("contextmenu", (e2) => {
      e2.preventDefault();
      const { x: mx, y: my } = this._getMouse(e2);
      const k2 = hitKey(mx, my);
      if (k2 && this.keys.length > 2) {
        this.keys = this.keys.filter((x3) => x3 !== k2);
        this.draw();
        this._reBake();
      }
    });
  }
  _timeToX(t3) {
    const w2 = this.width - this.padLeft;
    const R2 = 4;
    let x3 = t3 * w2;
    return Math.min(Math.max(x3, R2), w2 - R2);
  }
  // BAKING
  bake(samples = this.samples) {
    const data = new Float32Array(samples);
    for (let i2 = 0; i2 < samples; i2++) {
      const t3 = i2 / (samples - 1);
      data[i2] = this.getValue(t3);
    }
    return data;
  }
  _reBake() {
    this.baked = this.bake(this.samples);
  }
  exec(delta) {
    if (!this.isGraphRunning) return this.value;
    this.time += delta / this.length * this.speed;
    if (this.loop && this.time > 1) this.time = 0;
    if (!this.loop && this.time > 1) {
      this.time = 1;
      this.stop();
    }
    const idx = Math.floor(this.time * (this.samples - 1));
    this.value = this.baked[idx];
    this.draw();
    return this.value;
  }
  // SYNTETIC FOR NOW 
  play() {
    if (this.isGraphRunning) return;
    this.isGraphRunning = true;
    this._lastTime = performance.now();
    this._runner = setInterval(() => {
      const now = performance.now();
      const delta = (now - this._lastTime) / 1e3;
      this._lastTime = now;
      this.exec(delta);
    }, 16);
  }
  stop() {
    this.isGraphRunning = false;
    if (this._runner) {
      clearInterval(this._runner);
      this._runner = null;
    }
    this.draw();
  }
  getValueNow() {
    return this.value;
  }
  _createPopup() {
    this.popup = document.createElement("div");
    this.popup.id = "curve-editor";
    Object.assign(this.popup.style, {
      position: "fixed",
      top: "20%",
      left: "20%",
      transform: "translate(-50%,-50%)",
      background: "#111",
      border: "1px solid #333",
      padding: "5px",
      display: "none",
      zIndex: 999,
      width: "650px",
      height: "409px",
      paddingLeft: "2px",
      paddingRight: "2px"
    });
    this.toolbarTitle = document.createElement("div");
    this.toolbarTitle.style.cssText = `
      display:flex;
      align-items:center;
      gap:10px;
      padding:4px 6px;
      background:#121822;
      border-bottom:1px solid #1c2533;
      font-size:12px;
      margin-bottom: 5px;
    `;
    this.toolbarTitle.innerHTML = `<h3>Curve Editor</h3>`;
    this.popup.appendChild(this.toolbarTitle);
    this.popup.appendChild(this.canvas);
    document.body.appendChild(this.popup);
  }
  toggleEditor() {
    this._editorOpen = !this._editorOpen;
    this.popup.style.display = this._editorOpen ? "block" : "none";
    this.draw();
  }
  _buildToolbar() {
    this.root = document.createElement("div");
    this.root.style.cssText = `
    background:#0b0f14;
    border:1px solid #1c2533;
    font-family:monospace;
    color:#cfd8dc;
    width:${this.width}px;
  `;
    this.toolbar = document.createElement("div");
    this.toolbar.style.cssText = `
    display:flex;
    align-items:center;
    gap:10px;
    padding:4px 6px;
    background:#121822;
    border-bottom:1px solid #1c2533;
    font-size:12px;
  `;
    this.nameInput = document.createElement("input");
    this.nameInput.value = this.name;
    this.nameInput.disabled = true;
    this.nameInput.style.cssText = `
    width:80px;
    background:#0b0f14;
    border:1px solid #1c2533;
    color:#fff;
    padding:2px 4px;
  `;
    this.nameInput.onchange = () => this.name = this.nameInput.value;
    this.playBtn = document.createElement("button");
    this.playBtn.textContent = "\u25B6";
    this.playBtn.style.cssText = `
      background:#1c2533;
      color:#fff;
      border:none;
      padding:2px 8px;
      cursor:pointer;
    `;
    this.playBtn.onclick = () => {
      this.isGraphRunning ? this.stop() : this.play();
    };
    this.lengthInput = document.createElement("input");
    this.lengthInput.type = "number";
    this.lengthInput.value = this.length;
    this.lengthInput.step = "0.1";
    this.lengthInput.style.cssText = `
      width:60px;
      background:#0b0f14;
      border:1px solid #1c2533;
      color:#fff;
      padding:2px 4px;
    `;
    this.lengthInput.onchange = () => {
      this.length = Math.max(0.01, parseFloat(this.lengthInput.value));
    };
    this.timeLabel = document.createElement("span");
    this.valueLabel = document.createElement("span");
    this.runLabel = document.createElement("span");
    this.snapBtn = document.createElement("button");
    this.snapBtn.textContent = "Snap";
    this.snapBtn.style.cssText = `
    background:#1c2533;
    color:#fff;
    border:none;
    padding:2px 6px;
    cursor:pointer;
  `;
    this.snapBtn.onclick = () => {
      this.snapEnabled = !this.snapEnabled;
      this.snapBtn.style.opacity = this.snapEnabled ? "1" : "0.4";
    };
    const lenLabel = document.createElement("span");
    lenLabel.textContent = "Len";
    this.resetBtn = document.createElement("button");
    this.resetBtn.textContent = "Reset";
    this.resetBtn.style.cssText = this.snapBtn.style.cssText;
    this.resetBtn.onclick = () => {
      this.time = 0;
      this.draw();
    };
    this.saveBtn = document.createElement("button");
    this.saveBtn.textContent = "\u{1F4BE} Save";
    this.saveBtn.style.cssText = `
      background:#1c2533;
      color:#fff;
      border:none;
      padding:2px 6px;
      cursor:pointer;
    `;
    this.saveBtn.onclick = () => {
      let curve = this.curveStore.getByName(this.name);
      if (!curve) {
        curve = new CurveData(this.name);
        this.curveStore.curves.push(curve);
      }
      curve.keys = this.keys.map((k2) => ({ ...k2 }));
      curve.length = this.length;
      curve.loop = this.loop;
      curve.bake(this.samples);
      this.curveStore.save(curve);
      byId2("saveMainGraphDOM").click();
      console.log(`%c Curve [${this.name}] saved`, "color:#4caf50;font-weight:bold");
    };
    this.hideBtn = document.createElement("button");
    this.hideBtn.textContent = "Hide";
    this.hideBtn.style.cssText = `
      background:#1c2533;
      color:#fff;
      border:none;
      padding:2px 6px;
      cursor:pointer;
    `;
    this.hideBtn.onclick = () => {
      this.toggleEditor();
      console.log(`%c Curve [${this.name}] saved!`, LOG_FUNNY_ARCADE);
    };
    this.toolbar.append(
      this.nameInput,
      this.playBtn,
      lenLabel,
      this.lengthInput,
      this.timeLabel,
      this.valueLabel,
      this.runLabel,
      this.snapBtn,
      this.resetBtn,
      this.saveBtn,
      this.hideBtn
    );
    this.root.append(this.toolbar);
    this.popup.appendChild(this.root);
  }
  _updateToolbar = () => {
    this.currentValue = this.getValueNow();
    const timeSec = this.time * this.length;
    this.timeLabel.textContent = `T: ${timeSec.toFixed(2)}s`;
    this.valueLabel.textContent = `V: ${this.currentValue.toFixed(3)}`;
    this.runLabel.textContent = this.isGraphRunning ? "ACTIVE" : "STOPED";
    this.runLabel.style.color = this.isGraphRunning ? "#4caf50" : "#ff9800";
    this.playBtn.textContent = this.isGraphRunning ? "\u23F8" : "\u25B6";
  };
  _enableDrag() {
    const el2 = this.popup;
    const handle = this.toolbar;
    const handle2 = this.toolbarTitle;
    let isDown = false;
    let startX = 0;
    let startY = 0;
    let startLeft = 0;
    let startTop = 0;
    handle.style.cursor = "move";
    handle2.style.cursor = "move";
    handle.addEventListener("mousedown", (e2) => {
      isDown = true;
      startX = e2.clientX;
      startY = e2.clientY;
      const rect = el2.getBoundingClientRect();
      startLeft = rect.left;
      startTop = rect.top;
      document.body.style.userSelect = "none";
    });
    handle2.addEventListener("mousedown", (e2) => {
      isDown = true;
      startX = e2.clientX;
      startY = e2.clientY;
      const rect = el2.getBoundingClientRect();
      startLeft = rect.left;
      startTop = rect.top;
      document.body.style.userSelect = "none";
    });
    window.addEventListener("mousemove", (e2) => {
      if (!isDown) return;
      const dx = e2.clientX - startX;
      const dy = e2.clientY - startY;
      el2.style.left = startLeft + dx + "px";
      el2.style.top = startTop + dy + "px";
      el2.style.transform = "none";
    });
    window.addEventListener("mouseup", () => {
      isDown = false;
      document.body.style.userSelect = "";
    });
  }
  bindCurve(curve, meta = {}) {
    this.curve = curve;
    this.keys = curve.keys;
    this.length = curve.length;
    this.loop = curve.loop;
    this.name = meta.idNode;
    this.nameInput.value = this.name;
    this.lengthInput.value = this.length;
    this.idNode = meta.idNode ?? null;
    this.time = 0;
    this._reBake();
    this.draw();
  }
};
var CurveData = class {
  constructor(name2) {
    this.name = name2;
    this.keys = [
      { time: 0, value: 0, inTangent: 0, outTangent: 0 },
      { time: 1, value: 1, inTangent: 0, outTangent: 0 }
    ];
    this.length = 1;
    this.loop = true;
    this.samples = 128;
    this.baked = null;
  }
  getValue(t3) {
    t3 = Math.max(0, Math.min(1, t3));
    for (let i2 = 0; i2 < this.keys.length - 1; i2++) {
      const k0 = this.keys[i2];
      const k1 = this.keys[i2 + 1];
      if (t3 >= k0.time && t3 <= k1.time) {
        const dt2 = k1.time - k0.time;
        const u2 = (t3 - k0.time) / dt2;
        const u22 = u2 * u2;
        const u3 = u22 * u2;
        const m0 = k0.outTangent * dt2;
        const m1 = k1.inTangent * dt2;
        return (2 * u3 - 3 * u22 + 1) * k0.value + (u3 - 2 * u22 + u2) * m0 + (-2 * u3 + 3 * u22) * k1.value + (u3 - u22) * m1;
      }
    }
    return this.keys.at(-1).value;
  }
  // bake real values, not normalized 0-1
  bake(samples = this.samples) {
    this.baked = new Float32Array(samples);
    for (let i2 = 0; i2 < samples; i2++) {
      const t3 = i2 / (samples - 1);
      this.baked[i2] = this.getValue(t3);
    }
  }
  evaluate(time01) {
    if (!this.baked) {
      console.warn("Curve not baked!");
      return 0;
    }
    let t3 = time01;
    if (this.loop) t3 = t3 % 1;
    else t3 = Math.min(1, Math.max(0, t3));
    const idx = Math.floor(t3 * (this.baked.length - 1));
    return this.baked[idx];
  }
};
var CurveStore = class {
  constructor() {
    this.CURVE_STORAGE_KEY = "PROJECT_NAME";
    this.curves = [];
    this.load();
  }
  has(name2) {
    return this.curves.some((c2) => c2.name === name2);
  }
  getOrCreate(curveArg) {
    let curve = this.curves.find((c2) => c2.name === curveArg.name);
    if (curve) return curve;
    curve = new CurveData(curveArg.name);
    this.curves.push(curve);
    return curve;
  }
  getByName(name2) {
    return this.curves.find((c2) => c2.name === name2) || null;
  }
  add(curve) {
    this.curves.push(curve);
    this.save();
  }
  removeByName(name2) {
    this.curves = this.curves.filter((c2) => c2.name !== name2);
    this.save();
  }
  getAll() {
    return this.curves;
  }
  // SAVE / LOAD
  save() {
    console.log("TEST SAVE", this.curves);
    const data = {
      version: 1,
      curves: this.curves
    };
    localStorage.setItem(this.CURVE_STORAGE_KEY, JSON.stringify(data));
  }
  // saveCurve(curveData) {
  //   const idx = this.curves.findIndex(c => c.name === curveData.name);
  //   if(idx >= 0) {
  //     this.curves[idx] = curveData;
  //   } else {
  //     this.curves.push(curveData);
  //   }
  //   this.save();
  // }
  load() {
    const raw = localStorage.getItem(this.CURVE_STORAGE_KEY);
    if (!raw) return;
    try {
      const data = JSON.parse(raw);
      if (!data.curves) return;
      this.curves = data.curves.map((c2) => this._fromJSON(c2));
    } catch (e2) {
      console.warn("CurveStore load failed", e2);
      this.curves = [];
    }
  }
  _fromJSON(obj2) {
    const c2 = new CurveData(obj2.name);
    c2.keys = obj2.keys || [];
    c2.length = obj2.length ?? 1;
    c2.loop = !!obj2.loop;
    return c2;
  }
};

