  createGizmoIcons() {
    this.gizmoBox = document.createElement("div");
    this.assetsBox.id = "gizmoBox";
    Object.assign(this.gizmoBox.style, {
      position: "absolute",
      top: "0",
      left: "17.55%",
      width: "190px",
      height: "64px",
      backgroundColor: "transparent",
      display: "flex",
      alignItems: "start",
      color: "white",
      zIndex: "10",
      padding: "2px",
      boxSizing: "border-box",
      flexDirection: "row"
    });
    this.gizmoBox.innerHTML = `
    <div>
    <img id="mode0" data-mode="0" class="gizmo-icon" src="./res/textures/editor/0.png" width="48px" height="48px"/>
    <img id="mode1" data-mode="1" class="gizmo-icon" src="./res/textures/editor/1.png" width="48px" height="48px"/>
    <img id="mode2" data-mode="2" class="gizmo-icon" src="./res/textures/editor/2.png" width="48px" height="48px"/>
    </div>
    `;
    document.body.appendChild(this.gizmoBox);
    if (!document.getElementById("gizmo-style")) {
      const style = document.createElement("style");
      style.id = "gizmo-style";
      style.innerHTML = `
            .gizmo-icon {
                cursor: pointer;
                transition: all 0.2s ease-in-out;
                border-radius: 4px;
                padding: 4px;
            }
            /* Hover State */
            .gizmo-icon:hover {
                background-color: rgba(255, 255, 255, 0.15);
                transform: scale(1.1);
                filter: brightness(1.2);
            }
            /* Active/Click State */
            .gizmo-icon:active {
                transform: scale(0.95);
                background-color: rgba(255, 255, 255, 0.3);
            }
        `;
      document.head.appendChild(style);
    }
    const setMode = (e2) => {
      if (byId2("graph-status").innerHTML !== "\u26AB") return;
      let m2 = parseInt(e2.target.getAttribute("data-mode"));
      dispatchEvent(new CustomEvent("editor-set-gizmo-mode", { detail: { mode: m2 } }));
      if (m2 == 0) {
        byId2("mode0").style.border = "gray 1px solid";
        byId2("mode1").style.border = "none";
        byId2("mode2").style.border = "none";
      } else if (m2 == 1) {
        byId2("mode0").style.border = "none";
        byId2("mode1").style.border = "gray 1px solid";
        byId2("mode2").style.border = "none";
      } else if (m2 == 2) {
        byId2("mode0").style.border = "none";
        byId2("mode1").style.border = "none";
        byId2("mode2").style.border = "gray 1px solid";
      }
    };
    ["mode0", "mode1", "mode2"].forEach((id2) => {
      byId2(id2).addEventListener("pointerdown", setMode);
    });
    this.toolTip.attachTooltip(byId2("mode0"), `Set gizmo mode to 'translate'.
`);
    this.toolTip.attachTooltip(byId2("mode1"), `Set gizmo mode to 'rotate'.
`);
    this.toolTip.attachTooltip(byId2("mode2"), `Set gizmo mode to 'scale'.
`);
  }
  createAssets() {
    this.assetsBox = document.createElement("div");
    this.assetsBox.id = "assetsBox";
    Object.assign(this.assetsBox.style, {
      position: "absolute",
      bottom: "0",
      left: "17.55%",
      width: "63%",
      height: "250px",
      backgroundColor: "rgba(0,0,0,0.85)",
      display: "flex",
      alignItems: "start",
      color: "white",
      fontFamily: "'Orbitron', sans-serif",
      zIndex: "15",
      padding: "2px",
      boxSizing: "border-box",
      flexDirection: "column"
    });
    this.assetsBox.innerHTML = "ASSTES";
    this.assetsBox.innerHTML = `
    <div id="folderTitle" >Root</div>
    <div id="folderBack" class="scenePropItem" >...</div>
    <div id='res-folder' class="file-browser">
    </div>`;
    document.body.appendChild(this.assetsBox);
    byId2("folderBack").addEventListener("click", () => {
      let getCurrent = byId2("res-folder").getAttribute("data-root-folder");
      const t3 = getCurrent.substring(0, getCurrent.lastIndexOf("\\"));
      const last = t3.substring(t3.lastIndexOf("\\") + 1);
      if (last == "public") {
        return;
      }
      document.dispatchEvent(new CustomEvent("nav-folder", {
        detail: {
          rootFolder: t3 || "",
          name: ""
        }
      }));
    });
    this.toolTip.attachTooltip(byId2("folderTitle"), `This represent real folders files present intro res folder (what ever is there).

    From assets box you can add glb or obj files direct with simple click. Everyting will be saved automatic.

    Support for mp3 adding by click also. No support for mp4 - mp4 can be added from 'Set Textures' node.
    `);
    document.addEventListener("la", (e2) => {
      console.log(`%c[Editor]Root Resource Folder: ${e2.detail.rootFolder}`, LOG_FUNNY_ARCADE);
      byId2("res-folder").setAttribute("data-root-folder", e2.detail.rootFolder);
      byId2("res-folder").innerHTML = "";
      e2.detail.payload.forEach((i2) => {
        let item = document.createElement("div");
        item.classList.add("file-item");
        if (i2.isDir == true) {
          item.classList.add("folder");
        } else if (i2.name.split(".")[1] == "jpg" || i2.name.split(".")[1] == "png" || i2.name.split(".")[1] == "jpeg") {
          item.classList.add("png");
        } else if (i2.name.split(".")[1] == "mp3") {
          item.classList.add("mp3");
        } else if (i2.name.split(".")[1] == "js") {
          item.classList.add("js");
        } else if (i2.name.split(".")[1] == "ttf" || i2.name.split(".")[1] == "ttf" || i2.name.split(".")[1] == "TTF" || i2.name.split(".")[1] == "otf" || i2.name.split(".")[1] == "woff" || i2.name.split(".")[1] == "woff2") {
          item.classList.add("ttf");
        } else if (i2.name.split(".")[1] == "glb") {
          item.classList.add("glb");
        } else {
          item.classList.add("unknown");
        }
        item.innerHTML = "<p>" + i2.name + "</p>";
        byId2("res-folder").appendChild(item);
        item.addEventListener("click", (e3) => {
          if (i2.isDir == true) document.dispatchEvent(new CustomEvent("nav-folder", {
            detail: {
              rootFolder: byId2("res-folder").getAttribute("data-root-folder") || "",
              name: item.children[0].innerText
            }
          }));
          if (i2.isDir == false) document.dispatchEvent(new CustomEvent("file-detail", {
            detail: {
              rootFolder: byId2("res-folder").getAttribute("data-root-folder") || "",
              name: item.innerText
            }
          }));
        });
      });
      document.querySelectorAll(".file-item").forEach((el2) => {
        el2.addEventListener("click", () => {
          document.querySelectorAll(".file-item").forEach((x3) => x3.classList.remove("selected"));
          el2.classList.add("selected");
        });
      });
    });
  }
