// examples/physics-test-cannones.js
var testCannonES = function() {
  let physicsPlayground2 = new MatrixEngineWGPU({
    canvasSize: "fullscreen",
    useCannon: true,
    fastRender: 0.9,
    MAX_SPOTLIGHTS: 1,
    MAX_BONES: 0,
    mainCameraParams: {
      type: "WASD",
      responseCoef: 1e3
    },
    clearColor: { r: 0, b: 0.122, g: 0.122, a: 1 }
  }, () => {
    physicsPlayground2.addLight();
    addRaycastsListener();
    addEventListener("PhysicsReady", () => {
      downloadMeshes({
        cube: "./res/meshes/blender/cube.obj",
        plane: "./res/meshes/blender/plane.obj",
        ball: "./res/meshes/shapes/sphere-uv-cilinder-proj.obj",
        reel: "./res/meshes/obj/reel.obj"
      }, onGround, { scale: [1, 1, 1] });
      physicsPlayground2.matrixPhysics.speedUpSimulation(2);
      physicsPlayground2.physicsBodiesChain();
      app.physicsBodiesGeneratorWall(
        "standard",
        { x: -4.5, y: 1, z: -10 },
        { x: 0, y: 0, z: 0 },
        ["./res/textures/rust.jpg"],
        "my_set_walls",
        "5x3",
        true,
        [1, 1, 1],
        2.05,
        1e3,
        "ByZ"
      );
      let strength = 10;
      physicsPlayground2.canvas.addEventListener("ray.hit.event", (e2) => {
        console.log("ray.hit.event detected");
        let b2 = app.matrixPhysics.getBodyByName(e2.detail.hitObject.name);
        app.matrixPhysics.applyImpulse(b2, new PVector(
          e2.detail.rayDirection[0] * strength,
          e2.detail.rayDirection[1] * strength,
          e2.detail.rayDirection[2] * strength
        ));
      });
    });
    async function onGround(m2) {
      let cam2 = app.getCamera();
      cam2.setYaw(-0.03);
      cam2.setPitch(-0.49);
      cam2.setZ(0);
      cam2.setY(3.76);
      cam2._dirtyAngle = true;
      physicsPlayground2.addMeshObj({
        position: { x: 0, y: -0.5, z: -10 },
        rotation: { x: 0, y: 0, z: 0 },
        rotationSpeed: { x: 0, y: 0, z: 0 },
        scale: [25, 0.1, 25],
        // chatgpt-gen-bg-inv
        texturesPaths: ["res/icons/editor/chatgpt-gen-bg-inv.webp"],
        name: "ground",
        mesh: m2.plane,
        physics: { enabled: false }
      });
      if (isMobile() == false) app.activateBloomEffect();
      physicsPlayground2.lightContainer[0].setPosY(14);
      physicsPlayground2.lightContainer[0].setIntensity(24);
    }
  });
  window.app = physicsPlayground2;
};

// examples/canvas-inline.js
var canvasInline = function() {
  let loadObjFile2 = new MatrixEngineWGPU({
    canvasSize: "fullscreen",
    fastRender: 0.85,
    dontUsePhysics: true,
    MAX_SPOTLIGHTS: isMobile() ? 1 : 2,
    MAX_BONES: 0,
    mainCameraParams: {
      type: "WASD",
      responseCoef: 1e3
    },
    clearColor: { r: 0, b: 0, g: 0, a: 0 }
  }, () => {
    loadObjFile2.addLight();
    downloadMeshes(
      { ball: "./res/meshes/blender/sphere.obj", cube: "./res/meshes/blender/plane.obj" },
      onLoadObj,
      { scale: [1, 1, 1] }
    );
    downloadMeshes({ plane: "./res/meshes/blender/plane.obj" }, onGround, { scale: [30, 0.5, 30] });
    addRaycastsAABBListener("canvas1", "click");
    function onGround(m2) {
      let floor2 = loadObjFile2.addMeshObj({
        material: { type: "standard" },
        position: { x: 0, y: -5, z: -10 },
        rotation: { x: 0, y: 0, z: 0 },
        rotationSpeed: { x: 0, y: 0, z: 0 },
        texturesPaths: ["./res/textures/floor1.webp"],
        //, './res/textures/env-maps/sky1_lod_mid.webp'],
        name: "floor",
        mesh: m2.plane,
        physics: {
          enabled: false,
          mass: 0,
          geometry: "Cube"
        }
      });
      setTimeout(() => {
        const checker2 = floor2.createCheckerboardTexture(256, 128, [0, 50, 50, 255], [20, 200, 200, 255]);
        let samplerTest = loadObjFile2.device.createSampler({
          magFilter: "nearest",
          minFilter: "nearest",
          addressModeU: "repeat",
          addressModeV: "repeat"
        });
        floor2.changeTexture(checker2, samplerTest);
        floor2.setUVScale(8, 8);
      }, 500);
    }
    async function onLoadObj(m2) {
      let VIDEO_ARG = {
        type: "canvas2d-inline",
        canvaInlineProgram: (() => {
          const COLS = Math.floor(512 / 14);
          const drops = Array.from({ length: COLS }, () => Math.floor(Math.random() * -40));
          const chars = "\u30A2\u30A4\u30A6\u30A8\u30AA\u30AB\u30AD\u30AF\u30B1\u30B3\u30A2\u30A4\u30A6\u30A8\u30AA";
          let frame = 0;
          function roundRect(ctx, x3, y3, w2, h2, r3) {
            ctx.beginPath();
            ctx.moveTo(x3 + r3, y3);
            ctx.lineTo(x3 + w2 - r3, y3);
            ctx.quadraticCurveTo(x3 + w2, y3, x3 + w2, y3 + r3);
            ctx.lineTo(x3 + w2, y3 + h2 - r3);
            ctx.quadraticCurveTo(x3 + w2, y3 + h2, x3 + w2 - r3, y3 + h2);
            ctx.lineTo(x3 + r3, y3 + h2);
            ctx.quadraticCurveTo(x3, y3 + h2, x3, y3 + h2 - r3);
            ctx.lineTo(x3, y3 + r3);
            ctx.quadraticCurveTo(x3, y3, x3 + r3, y3);
            ctx.closePath();
          }
          return (ctx) => {
            const W2 = ctx.canvas.width;
            const H2 = ctx.canvas.height;
            const pulse = 0.85 + 0.15 * Math.sin(frame * 0.06);
            ctx.fillStyle = "rgba(0, 0, 0, 0.01)";
            ctx.fillRect(0, 0, W2, H2);
            for (let i2 = 0; i2 < COLS; i2++) {
              const ch = chars[Math.floor(Math.random() * chars.length)];
              const br2 = Math.random();
              ctx.fillStyle = br2 > 0.82 ? "#ffffff4b" : `rgba(0,${Math.floor(160 + br2 * 95)},${Math.floor(br2 * 60)},${0.4 + br2 * 0.6})`;
              ctx.fillText(ch, i2 * 14, drops[i2] * 14);
              if (drops[i2] * 14 > H2 + 14 && Math.random() > 0.975) drops[i2] = 0;
              else drops[i2]++;
            }
            ctx.shadowColor = "#00ff4052";
            ctx.shadowBlur = 18 * pulse;
            frame++;
          };
        })()
      };
      let sky = loadObjFile2.addMeshObj({
        material: { type: "standard", share: true },
        position: { x: 0, y: -1, z: -20 },
        rotation: { x: 0, y: 0, z: 0 },
        scale: [100, 100, 100],
        rotationSpeed: { x: 0, y: 0.5, z: 0 },
        texturesPaths: ["./res/textures/env-maps/sky1_lod_mid.webp"],
        name: "sky",
        mesh: m2.ball,
        isVideo: VIDEO_ARG,
        physics: {
          enabled: false,
          geometry: "Sphere"
        }
      });
      let MYCUBE = loadObjFile2.addMeshObj({
        material: { type: "standard", share: true },
        position: { x: 0, y: 7, z: -10 },
        rotation: { x: 0, y: 0, z: 0 },
        scale: [7, 7, 7],
        rotationSpeed: { x: 0, y: 3, z: 0 },
        texturesPaths: ["./res/textures/env-maps/sky1_lod_mid.webp"],
        name: "cube",
        mesh: m2.cube,
        raycast: { enabled: true, radius: 1 },
        physics: {
          enabled: false,
          mass: 0,
          geometry: "Cube"
        }
        // pointerEffect: {
        //   enabled: true,
        //   flameEmitter: true
        //   // flameEffect: true
        // }
      });
      let MYCYLINDER = loadObjFile2.addProceduralMeshObj({
        material: { type: "standard", share: true },
        position: { x: 0, y: 7, z: -10 },
        rotation: { x: 0, y: 0, z: 0 },
        scale: [5, 5, 5],
        rotationSpeed: { x: 0, y: 0, z: 0 },
        texturesPaths: ["./res/textures/env-maps/sky1_lod_mid.webp"],
        meshA: MeshMorpher.sphere(1, 2),
        meshB: MeshMorpher.cube(1),
        name: `morph_1`,
        physics: {
          enabled: false
        },
        raycast: { enabled: true, radius: 1 }
      });
      loadObjFile2.lightContainer[0].setIntensity(10);
      loadObjFile2.activateBloomEffect();
      loadObjFile2.lightContainer[0].behavior.setOsc0(-2, 2, 0.01);
      loadObjFile2.lightContainer[0].behavior.value_ = -1;
      loadObjFile2.lightContainer[0].updater.push((light) => {
        light.setTargetX(light.behavior.setPath0());
        light.setPosX(light.behavior.setPath0());
      });
      loadObjFile2.lightContainer[0].setPosition(0, 25, -10);
      loadObjFile2.lightContainer[0].setTarget(0, 0, -10);
      setTimeout(() => {
        MYCUBE.loadVideoTexture(VIDEO_ARG);
        MYCUBE.setBlend(0.1);
        MYCUBE.setupPipeline();
        MYCYLINDER.loadVideoTexture(VIDEO_ARG);
        MYCYLINDER.setBlend(0.1);
        MYCYLINDER.setupPipeline();
        let cam2 = app.getCamera();
        cam2.setYaw(-0.03);
        cam2.setPitch(-0.49);
        cam2.setZ(5);
        cam2.setY(20);
        app.buildRenderBuckets();
        cam2._dirtyAngle = true;
      }, 800);
    }
    let STATUS = 1;
    loadObjFile2.canvas.addEventListener("ray.hit.event", (e2) => {
      if (e2.detail.hitObject.name == "morph_1") {
        e2.detail.hitObject.morphTo(STATUS);
        if (STATUS == 1) STATUS = 0;
        else STATUS = 1;
      }
    });
  });
  window.app = loadObjFile2;
};

