      t3.position[1] = 0;
      t3.position[2] = 0;
      t3.rotation[0] = 0;
      t3.rotation[1] = 0;
      t3.rotation[2] = 0;
      t3.scale[0] = 1;
      t3.scale[1] = 1;
      t3.scale[2] = 1;
      t3.color[0] = 1;
      t3.color[1] = 1;
      t3.color[2] = 1;
      t3.color[3] = 1;
