    this.typeOfController = o3.typeOfController || "fps";
    this.maxEnergy = o3.maxEnergy ?? 100;
    this.energy = o3.energy ?? this.maxEnergy;
    this.lives = o3.lives ?? 1;
    this.ammo = o3.ammo ?? 100;
    this.armor = o3.armor ?? false;
